CREATE POLICY "Admins can delete profiles" ON public.profiles FOR DELETE USING (has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can delete challenge progress" ON public.challenge_progress FOR DELETE USING (has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can delete training progress" ON public.training_progress FOR DELETE USING (has_role(auth.uid(), 'admin'::app_role));